-- #1482 - VendorEnquiry + VendorEnquiryReply: customer messages (storefront contact form and
-- inbound store email) shown in /staff/enquiries, and every reply sent from there, append-only.
--
-- HAND-AUTHORED, not generated by `prisma migrate dev --create-only`: that command refuses on the
-- dev database ("The migration `20260820200500_p8_image_needs_review` was modified after it was
-- applied") and offers only `migrate reset`, which would delete every row - the open `#895`. The DDL
-- below is Prisma's own output, unedited, from `prisma migrate diff --from-schema-datamodel
-- <staging schema> --to-schema-datamodel prisma/schema.prisma --script`, so it touches no database
-- and cannot propose removing the hand-authored `pg_trgm` indexes (`#508`).
--
-- Edited in place on 2026-11-10 (retro-spec specs/2026-11-10-pr1481-enquiries-team-access-retro/,
-- R29/R30): `prisma migrate status` showed it unapplied on dev, and it had never reached staging
-- or production. Purely additive: two enums, two tables, three indexes, two foreign keys.

-- CreateEnum
CREATE TYPE "EnquirySource" AS ENUM ('CONTACT_FORM', 'INBOUND_EMAIL');

-- CreateEnum
CREATE TYPE "EnquiryStatus" AS ENUM ('OPEN', 'REPLIED', 'RESOLVED');

-- CreateTable
CREATE TABLE "VendorEnquiry" (
    "id" TEXT NOT NULL,
    "vendorId" TEXT NOT NULL,
    "source" "EnquirySource" NOT NULL,
    "type" TEXT NOT NULL,
    "senderName" TEXT,
    "senderEmail" TEXT NOT NULL,
    "senderPhone" TEXT,
    "toAddress" TEXT,
    "orderNumber" TEXT,
    "subject" TEXT NOT NULL,
    "message" TEXT NOT NULL,
    "status" "EnquiryStatus" NOT NULL DEFAULT 'OPEN',
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "VendorEnquiry_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "VendorEnquiryReply" (
    "id" TEXT NOT NULL,
    "enquiryId" TEXT NOT NULL,
    "body" TEXT NOT NULL,
    "sentBy" TEXT NOT NULL,
    "sentAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "VendorEnquiryReply_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "VendorEnquiry_vendorId_createdAt_idx" ON "VendorEnquiry"("vendorId", "createdAt");

-- CreateIndex
CREATE INDEX "VendorEnquiry_vendorId_status_idx" ON "VendorEnquiry"("vendorId", "status");

-- CreateIndex
CREATE INDEX "VendorEnquiryReply_enquiryId_sentAt_idx" ON "VendorEnquiryReply"("enquiryId", "sentAt");

-- AddForeignKey
ALTER TABLE "VendorEnquiry" ADD CONSTRAINT "VendorEnquiry_vendorId_fkey" FOREIGN KEY ("vendorId") REFERENCES "Vendor"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "VendorEnquiryReply" ADD CONSTRAINT "VendorEnquiryReply_enquiryId_fkey" FOREIGN KEY ("enquiryId") REFERENCES "VendorEnquiry"("id") ON DELETE CASCADE ON UPDATE CASCADE;

